
const ST=['Draft','Pending Internal Review','Approved Internally','Sent to Customer','Customer Approved','Customer Rejected','Expired','Cancelled'];
const R=v=>Math.round((+v||0)*100),$=s=>document.querySelector(s),clone=x=>JSON.parse(JSON.stringify(x)),uid=()=>crypto.randomUUID().replaceAll('-','');
const nf=(p,pre)=>pre+(p/100).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}),inr=p=>nf(p,'₹'),rs=p=>nf(p,'Rs. ');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iso=d=>d.toISOString().slice(0,10),today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')},addD=(s,n)=>{const d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return iso(d)};
const fd=s=>s?s.split('-').reverse().join('/'):'',now=()=>new Date().toISOString();
let S,Q=null,CF=null,DL=null,D={r:'all',a:'',b:''},F={q:'',st:'',cu:'',sp:'',a:'',b:'',mn:'',mx:''},RF={a:'',b:''},CQ={q:'',c:''},CS='';

function toast(m,t){const e=document.createElement('div');e.className=t||'';e.textContent=m;$('#toast').append(e);setTimeout(()=>e.remove(),3500)}
function log(t){S.log.unshift({t:now(),x:t,u:S.user});S.log=S.log.slice(0,40)}
/* ---------- catalog seed (DEMO prices, configurable) ---------- */
const o=(v,t,a)=>[v,t||'f',a||0],sel=(k,l,op)=>({k,l,t:'sel',o:op}),T=(k,l)=>({k,l,t:'txt'}),SZ=['S','M','L','XL','XXL'];
const DEL=sel('deliv','Delivery',[o('Standard'),o('Express','p',20)]),NOTE=T('note','Notes'),DES=sel('design','Design Service',[o('Not Required'),o('Basic Design','f',250),o('Premium Design','f',800)]);
const SIDES=sel('sides','Printing Sides',[o('Single Side'),o('Double Side','p',25)]);
const TERMS=['This quotation is valid until the specified expiry date.','Prices and taxes are based on the specifications listed in this quotation.','Changes to approved specifications or quantities may change the quoted price.','Production timelines are subject to confirmation and approval of final artwork.','Any advance payment or payment schedule must be agreed upon before work begins.','Delivery and installation charges will be applied where applicable and as specified in the quotation.'];
/* ---------- pricing engine (integer paise) ---------- */
const AF=DP.AF;
const defCfg=DP.defCfg,calc=DP.calc,mkItem=DP.mkItem;
function tot(q){return DP.totals(q,S.set)}
/* ---------- helpers ---------- */
const prod=id=>S.products.find(p=>p.id===id),cust=id=>S.customers.find(c=>c.id===id)||{},cat=id=>(S.cats.find(c=>c.id===id)||{}).name||'';
const bg=s=>`<span class="bg ${/Approved$|Customer Approved/.test(s)&&s!=='Approved Internally'?'g':/Rejected|Cancelled|Expired/.test(s)?'r':/Pending|Sent/.test(s)?'y':''}">${esc(s)}</span>`;
const fld=(l,h)=>`<label class="f"><span>${esc(l)}</span>${h.replace(/^<(input|select|textarea)\b/,(_,tag)=>`<${tag} aria-label="${esc(l)}"`)}</label>`;
const modal=(h,w)=>{$('#modal').innerHTML=`<div class="box" style="max-width:${w||760}px"><button class="x b2 noprint" onclick="closeM()" aria-label="Close">✕</button>${h}</div>`;$('#modal').style.display='flex'};
const closeM=()=>{$('#modal').style.display='none';$('#modal').innerHTML=''};
let _fn;const ask=(m,fn,lbl)=>{_fn=fn;modal(`<p>${m}</p><div class="row"><button class="${lbl=='Delete'?'bd':''}" onclick="closeM();_fn()">${lbl||'Confirm'}</button><button class="b2" onclick="closeM()">Cancel</button></div>`,420)};
function nextNo(date){const y=date.slice(0,4),re=new RegExp('/'+y+'/(\\d+)$');let m=0;S.quotes.forEach(q=>{const x=re.exec(q.no);if(x)m=Math.max(m,+x[1])});return`${S.set.prefix}/${y}/${String(m+1).padStart(4,'0')}`}
function newQ(){return{id:'',no:'',date:today(),valid:addD(today(),+S.set.valid||15),cid:'',sales:S.user,ref:'',project:'',subject:'',req:'',items:[],chargeTax:S.set.tax,disc:{t:'p',v:0},del:0,oth:0,status:'Draft',terms:clone(S.set.terms),hist:[]}}
async function out(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows,name){const cell=value=>{let text=String(value??'');if(/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'};out(new Blob(['\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),name)}
/* ---------- views ---------- */
const NAV=[['dash','Dashboard'],['new','Create Quotation'],['list','All Quotations'],['cust','Customers'],['prod','Products & Services'],['cat','Product Categories'],['price','Pricing Configuration'],['rep','Reports'],['set','Settings']],V={};
const go=h=>{if(location.hash==='#'+h)render();else location.hash=h};
function inRange(){return S.quotes.filter(q=>{const t=today();return D.r==='all'||(D.r==='today'&&q.date===t)||(D.r==='week'&&q.date>=addD(t,-6))||(D.r==='month'&&q.date.slice(0,7)===t.slice(0,7))||(D.r==='custom'&&(!D.a||q.date>=D.a)&&(!D.b||q.date<=D.b))})}
const acts=q=>`<button class="s b2" onclick="viewQ('${q.id}')">View</button> <button class="s b2" onclick="editQ('${q.id}')">Edit</button> <button class="s b2" onclick="dupQ('${q.id}')">Duplicate</button> <button class="s b2" onclick="pdfQ('${q.id}')">PDF</button>`;
V.dash=()=>{const qs=inRange(),c=s=>qs.filter(q=>q.status===s).length,val=qs.reduce((a,q)=>a+tot(q).grand,0);
 return`<h1>Dashboard</h1><div class="row"><select style="width:auto" onchange="D.r=this.value;render()">${[['all','All time'],['today','Today'],['week','This week'],['month','This month'],['custom','Custom range']].map(x=>`<option value="${x[0]}" ${D.r==x[0]?'selected':''}>${x[1]}</option>`).join('')}</select>${D.r==='custom'?`<input type="date" style="width:auto" value="${D.a}" onchange="D.a=this.value;render()"><input type="date" style="width:auto" value="${D.b}" onchange="D.b=this.value;render()">`:''}<button class="bo" onclick="Q=null;go('new')">+ Create Quotation</button></div>
 <div class="cards">${[['Total Quotations',qs.length],['Draft',c('Draft')],['Sent to Customer',c('Sent to Customer')],['Customer Approved',c('Customer Approved')],['Customer Rejected',c('Customer Rejected')],['Quoted value (not revenue)',inr(val)]].map(x=>`<div class="card"><b>${x[1]}</b><span>${x[0]}</span></div>`).join('')}</div>
 <div class="card"><h2>Recent quotations</h2><div class="tw"><table><tr><th>Number</th><th>Date</th><th>Customer</th><th class="n">Items</th><th class="n">Total</th><th>Status</th><th>By</th><th>Actions</th></tr>${qs.slice(0,8).map(q=>`<tr><td>${esc(q.no)}</td><td>${fd(q.date)}</td><td>${esc(cust(q.cid).name)}</td><td class="n">${q.items.length}</td><td class="n">${inr(tot(q).grand)}</td><td>${bg(q.status)}</td><td>${esc(q.by)}</td><td>${acts(q)}</td></tr>`).join('')||'<tr><td colspan=8>No quotations in this range.</td></tr>'}</table></div></div>
 <div class="card"><h2>Recent activity</h2>${S.log.slice(0,8).map(l=>`<div class="mu">${new Date(l.t).toLocaleString('en-IN')} — ${esc(l.x)} (${esc(l.u)})</div>`).join('')}</div><div class="mu">Saved securely to your local backend database. Catalog prices are samples until reviewed by your administrator.</div>`};
/* --- create / edit quotation --- */
const cinfo=()=>{const c=cust(Q.cid);return Q.cid?`<div class="mu">${esc(c.co)} · ${esc(c.person||'')} · ${esc(c.mob)} · ${esc(c.email)}<br>${esc(c.addr)} ${c.gstin?'· GSTIN '+esc(c.gstin):''}</div>`:'<div class="mu">Select a customer or add a new one.</div>'};
V.new=()=>{if(!Q)Q=newQ();
 return`<h1>${Q.id?'Edit':'Create'} Quotation <span class="mu">${esc(Q.no||'Number assigned on save')}</span></h1>${Q.id&&!getQ(Q.id)?'<div class="note">The original quotation was deleted. Your draft is preserved. <button class="s b2" onclick="saveMissingAsNew()">Save as new Draft</button></div>':''}<div class="note">Prices come from the demo catalog — configurable sample prices, not Design Paradise's approved rates.</div>
 <div class="card"><h2>1. Customer</h2><div class="row"><select style="flex:1;min-width:200px" onchange="Q.cid=this.value;$('#ci').innerHTML=cinfo()"><option value="">Select existing customer…</option>${S.customers.map(c=>`<option value="${c.id}" ${c.id===Q.cid?'selected':''}>${esc(c.name)} — ${esc(c.mob)}</option>`).join('')}</select><button class="b2" onclick="custForm('',1)">+ New customer</button></div><div id="ci">${cinfo()}</div></div>
 <div class="card"><h2>2. Quotation details</h2><div class="grid">${fld('Quotation number','<input readonly value="'+esc(Q.no||'Number assigned on save')+'">')}${fld('Date',`<input type="date" value="${Q.date}" oninput="Q.date=this.value">`)}${fld('Valid until',`<input type="date" value="${Q.valid}" oninput="Q.valid=this.value">`)}${fld('Salesperson',`<input value="${esc(Q.sales)}" oninput="Q.sales=this.value">`)}${fld('Reference no.',`<input value="${esc(Q.ref)}" oninput="Q.ref=this.value">`)}${fld('Project name',`<input value="${esc(Q.project)}" oninput="Q.project=this.value">`)}${fld('Subject',`<input value="${esc(Q.subject)}" oninput="Q.subject=this.value">`)}${fld('Customer requirements',`<input value="${esc(Q.req)}" oninput="Q.req=this.value">`)}</div></div>
 <div class="card"><h2>3. Products and services</h2><div id="its">${itemsHTML()}</div><button class="bo" onclick="openCat()">+ Add product or service</button></div>
 <div class="card"><h2>4. Quotation-level charges, discount and terms</h2><div class="grid">${fld('Discount type',`<select onchange="Q.disc.t=this.value;upd()"><option value="p" ${Q.disc.t=='p'?'selected':''}>Percentage (%)</option><option value="f" ${Q.disc.t=='f'?'selected':''}>Fixed amount (₹)</option></select>`)}${fld('Discount value',`<input type="number" min="0" value="${Q.disc.v}" oninput="Q.disc.v=+this.value||0;upd()">`)}${fld('Delivery charges (₹)',`<input type="number" min="0" value="${Q.del}" oninput="Q.del=+this.value||0;upd()">`)}${fld('Other charges (₹)',`<input type="number" min="0" value="${Q.oth}" oninput="Q.oth=+this.value||0;upd()">`)}</div><div class="mu">Delivery/other charges are quotation-level only (taxed at the saved rate ${Q.chargeTax??S.set.tax}%). Item charges are inside each item, so nothing is counted twice.</div><br>${fld('Terms and conditions (one per line, editable)',`<textarea rows="5" oninput="Q.terms=termsFromText(this.value)">${esc(Q.terms.join('\n'))}</textarea>`)}</div>
 <div class="card"><h2>5. Summary</h2><div id="sm">${sumHTML(Q)}</div><div class="row" style="margin-top:12px"><button onclick="saveQ(1)">${Q.id?'Save quotation':'Save as Draft'}</button><button class="b2" onclick="prevQ()">Preview Quotation</button><button class="bo" onclick="pdfCur()">Generate PDF</button>${Q.id?`<button class="b2" onclick="dupQ(Q.id)">Duplicate Quotation</button><button class="b2" onclick="refreshP()">Refresh prices from catalog</button>`:''}<button class="b2" onclick="Q=null;go('dash')">Cancel</button></div></div>`};
function upd(){if($('#its'))$('#its').innerHTML=itemsHTML();if($('#sm'))$('#sm').innerHTML=sumHTML(Q)}
const itemsHTML=()=>Q.items.length?`<div class="tw"><table><tr><th>#</th><th>Product</th><th class="n">Qty</th><th class="n">Amount</th><th>Actions</th></tr>${Q.items.map((i,k)=>`<tr><td>${k+1}</td><td><b>${esc(i.name)}</b><details><summary class="mu">Specifications &amp; calculation</summary>${i.sp.map(esc).join('<br>')}<br><span class="mu">${i.L.map(l=>esc(l[0])+' = '+inr(l[1])).join('<br>')}</span></details>${i.notes?`<div class="mu">Internal note: ${esc(i.notes)}</div>`:''}</td><td class="n">${i.qty}</td><td class="n">${inr(i.sub)}</td><td><button class="s b2" onclick="openCfg('${i.pid}','${i.id}')">Edit</button> <button class="s b2" onclick="dupItem('${i.id}')">Duplicate</button> <button class="s b2" onclick="noteItem('${i.id}')">Note</button> <button class="s bd" onclick="rmItem('${i.id}')">Remove</button></td></tr>`).join('')}</table></div>`:'<p class="mu">No items yet. Add at least one product or service.</p>';
function sumHTML(q){let t;try{t=tot(q)}catch(error){return '<div class="note">'+esc(error.message)+'</div>'}const r=(a,b,c)=>`<tr class="${c||''}"><td>${a}</td><td class="n">${b}</td></tr>`;
 return`<div class="mu">Items: ${t.n} · Total quantity: ${t.qty}</div>${t.warn?'<div class="note">Discount exceeds the product subtotal and was capped so the taxable amount cannot go negative.</div>':''}<table class="tot" style="max-width:420px;margin-left:auto">${r('Product subtotal',inr(t.ib))}${r('Item-level charges',inr(t.ic))}${r('Delivery &amp; other charges',inr(t.qc))}${r('Discount','− '+inr(t.disc))}${r('Taxable amount',inr(t.taxable))}${t.br.map(b=>r(`CGST ${b.r/2}% + SGST ${b.r/2}% on ${inr(b.t)}`,inr(b.x))).join('')}${r('Grand total',inr(t.grand),'g')}</table>`}
function dupItem(id){const i=Q.items.find(x=>x.id===id);Q.items.push(Object.assign(clone(i),{id:uid()}));upd()}
function rmItem(id){Q.items=Q.items.filter(x=>x.id!==id);upd()}
function noteItem(id){const i=Q.items.find(x=>x.id===id);modal(`<h2>Internal note</h2><div class="mu">Not shown on customer PDFs unless enabled in Settings.</div><textarea id="nt" rows="3">${esc(i.notes)}</textarea><br><br><button onclick="Q.items.find(x=>x.id==='${id}').notes=$('#nt').value;closeM();upd()">Save note</button>`,460)}
/* catalog + configurator */
function openCat(){CS='';modal(`<h2>Select a product</h2><div class="row"><input id="cq" style="flex:1" placeholder="Search products…" oninput="$('#cl').innerHTML=catList()"><select id="cc2" style="width:auto" onchange="$('#cl').innerHTML=catList()"><option value="">All categories</option>${S.cats.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="grid" id="cl">${catList()}</div>`)}
function catList(){const q=($('#cq')?.value||'').toLowerCase(),c=$('#cc2')?.value||'';return S.products.filter(p=>p.on&&S.cats.some(x=>x.id===p.cat&&x.on)&&(!c||p.cat===c)&&p.name.toLowerCase().includes(q)).map(p=>`<div class="card pc" onclick="openCfg('${p.id}')"><b>${esc(p.name)}</b><div class="mu">${esc(cat(p.cat))} · ${p.m==='unit'?'per unit, quantity tiers':p.m==='area'?'per sq ft':'fixed package'}</div></div>`).join('')||'<p class="mu">No matching products.</p>'}
function openCfg(pid,iid){const p=prod(pid);if(!p){toast('This product was removed from the catalog. Its saved quotation price is preserved.','wa');return}const it=iid?Q.items.find(x=>x.id===iid):null;CF=it?clone(it.cfg):defCfg(p);CF._p=pid;CF._i=iid||'';
 const fields=p.f.filter(f=>p.m==='area'||f.t!=='dim');if(p.m==='area'&&!fields.some(f=>f.t==='dim'))fields.unshift({k:'dim',l:'Size',t:'dim'});
 const f=fields.map(f=>f.t==='sel'?fld(f.l,`<select onchange="cs_('${f.k}',this.value)">${f.o.map(x=>`<option ${CF[f.k]===x[0]?'selected':''}>${esc(x[0])}</option>`).join('')}</select>`):f.t==='txt'?fld(f.l,`<input value="${esc(CF[f.k]||'')}" oninput="cs_('${f.k}',this.value)">`):fld('Custom size',`<div class="row" style="margin:0"><input type="number" min="0" step="any" value="${CF.w}" oninput="cs_('w',this.value)" placeholder="Width"><input type="number" min="0" step="any" value="${CF.h}" oninput="cs_('h',this.value)" placeholder="Height"><select style="width:90px" onchange="cs_('u',this.value)">${Object.keys(AF).map(u=>`<option ${CF.u===u?'selected':''}>${u}</option>`).join('')}</select></div>`)).join('');
 const q=p.sizes&&p.m==='unit'?`<div>${fld('Size breakdown (total is calculated)',`<div class="row" style="margin:0">${SZ.map(k=>`<label class="f" style="width:64px"><span>${k}</span><input type="number" min="0" value="${CF.sz[k]||0}" oninput="CF.sz['${k}']=+this.value;refCalc()"></label>`).join('')}</div>`)}</div>`:p.m==='fixed'?'':fld('Quantity'+(p.m==='area'?' (pieces)':''),`<input type="number" min="1" value="${CF.qty}" oninput="cs_('qty',this.value)">`);
 modal(`<h2>${esc(p.name)} <span class="mu">${it?'— editing item':''}</span></h2>${p.tiers?`<div class="mu">Demo tiers: ${p.tiers.map(t=>t[0]+'+ → '+inr(R(t[1]))).join(' · ')}. Custom quantities use the highest tier at or below the quantity; below the first tier is rejected.</div>`:''}<div class="grid" style="margin:10px 0">${q}${f}</div><div id="cc"></div><div class="row" style="margin-top:10px"><button class="bo" onclick="addItem()">${it?'Update item':'Add to quotation'}</button><button class="b2" onclick="${it?'closeM()':'openCat()'}">Back</button></div>`,820);refCalc()}
function cs_(k,v){CF[k]=['qty','w','h'].includes(k)?Number(v):v;refCalc()}
function refCalc(){const p=prod(CF._p),r=calc(p,CF);$('#cc').innerHTML=r.err?`<div class="note">${esc(r.err)}</div>`:`<div class="card"><table class="tot"><tr><td>Quantity</td><td class="n">${r.qty}</td></tr>${r.L.map(l=>`<tr><td>${esc(l[0])}</td><td class="n">${inr(l[1])}</td></tr>`).join('')}<tr><td><b>Item subtotal</b></td><td class="n"><b>${inr(r.sub)}</b></td></tr><tr><td>GST at ${p.tax}% (demo rate)</td><td class="n">${inr(r.gst)}</td></tr><tr class="g"><td>Item total incl. GST</td><td class="n">${inr(r.sub+r.gst)}</td></tr><tr><td class="mu">Effective unit price (ex-GST)</td><td class="n mu">${inr(r.eff)}</td></tr></table><div class="mu">Specification summary: ${r.sp.map(esc).join(' · ')}. Discount is applied at quotation level.</div></div>`}
function addItem(){const p=prod(CF._p),old=Q.items.find(x=>x.id===CF._i),it=mkItem(p,CF,CF._i,old&&old.notes);if(!it){toast(calc(p,CF).err,'er');return}if(old)Q.items[Q.items.indexOf(old)]=it;else Q.items.push(it);closeM();upd();toast('Item '+(old?'updated':'added'))}
function refreshP(){ask('Recalculate every item using the CURRENT catalog prices? Original quoted prices on this quotation will be replaced.',()=>{Q._refreshPrices=true;Q.items=Q.items.map(i=>{const p=prod(i.pid);return(p&&mkItem(p,i.cfg,i.id,i.notes))||i});upd();toast('Prices refreshed from catalog','wa')})}
/* save / status / preview / pdf */
function okQ(fin){if(!Q.cid){toast('Select or create a customer first.','er');return false}if(fin&&!Q.items.length){toast('Add at least one product or service.','er');return false}if(fin&&(!Q.date||!Q.valid||Q.valid<Q.date)){toast('Valid-until date must be on or after the quotation date.','er');return false}return true}
async function saveQ(show){
 if(busy||!okQ(0))return false;
 if(Q.id&&!getQ(Q.id)){status('error','This quotation was deleted in another session. Your draft is preserved; copy it into a new Draft to save it.');toast('This quotation no longer exists. Use Save as new Draft.','er');render();return false}
 rebaseDraft();
 const draft=clone(Q),i=S.quotes.findIndex(x=>x.id===draft.id);
 if(i<0){draft.id='Q'+uid();draft.status='Draft';S.quotes.unshift(draft)}else S.quotes[i]=draft;
 if(!await persist())return false;
 Q=clone(getQ(draft.id));
 if(show){toast('Saved '+Q.no);render()}
 return true;
}
const getQ=id=>S.quotes.find(q=>q.id===id);
function rebaseDraft(){if(!Q?.id)return;const saved=getQ(Q.id);if(!saved)return;for(const key of ['status','hist','no','by','chargeTax']){if(saved[key]!==undefined)Q[key]=clone(saved[key]);else delete Q[key]}}
function saveMissingAsNew(){if(!Q?.id||getQ(Q.id))return;ask('The original quotation was deleted. Save these details as a new Draft with a new quotation number?',async()=>{Q.id='';Q.no='';Q.status='Draft';Q.hist=[];delete Q.by;Q.chargeTax=S.set.tax;await saveQ(true)},'Save as new Draft')}
function viewQ(id){const q=getQ(id);modal(docHTML(q)+`<h2 class="noprint" style="margin-top:14px">Status history</h2><div class="mu noprint">${q.hist.map(h=>`${new Date(h.d).toLocaleString('en-IN')}: ${esc(h.f)} → ${esc(h.t)} (${esc(h.u)})`).join('<br>')}</div><div class="row noprint" style="margin-top:10px"><button onclick="pdfQ('${id}')">Download PDF</button><button class="b2" onclick="window.print()">Print</button><button class="b2" onclick="statusQ('${id}')">Change status</button></div>`,900)}
function prevQ(){if(!okQ(1))return;modal(docHTML(Q)+`<div class="row noprint" style="margin-top:10px"><button onclick="pdfCur()">Generate PDF</button><button class="b2" onclick="window.print()">Print</button></div>`,900)}
function editQ(id){Q=clone(getQ(id));go('new')}
async function dupQ(id){
 if(busy)return;const original=getQ(id),q=clone(original);
 q.id='Q'+uid();q.no='';q.date=today();q.valid=addD(today(),+S.set.valid||15);q.status='Draft';q.hist=[];
 S.quotes.unshift(q);if(!await persist())return;
 toast('Duplicated as '+getQ(q.id).no);Q=null;render();
}
function delQ(id){const q=getQ(id);if(S.role!=='Administrator'&&!['Draft','Cancelled'].includes(q.status)){toast('Only an administrator can delete quotations that are not Draft or Cancelled.','er');return}ask(`Delete ${esc(q.no)} permanently?`,async()=>{S.quotes=S.quotes.filter(x=>x.id!==id);if(!await persist())return;if(Q?.id===id)Q=null;render();toast('Quotation deleted')},'Delete')}
function statusQ(id){const q=getQ(id);modal(`<h2>Change status - ${esc(q.no)}</h2><div class="mu">Only an administrator can approve an internal review. Downloading a PDF never changes status.</div><br>${fld('New status',`<select id="ns">${ST.filter(s=>s!=='Approved Internally'||S.role==='Administrator'||q.status===s).map(s=>`<option ${s===q.status?'selected':''}>${esc(s)}</option>`).join('')}</select>`)}<br><button onclick="setSt('${id}')">Update status</button>`,440)}
async function setSt(id){if(busy)return;const q=getQ(id),n=$('#ns').value;if(n===q.status){closeM();return}if(!q.items.length&&n!=='Cancelled'){toast('Add at least one item before moving past Draft.','er');return}q.status=n;if(!await persist())return;closeM();rebaseDraft();render();toast('Status updated')}
function docHTML(q){const t=tot(q),c=q.customerSnapshot||cust(q.cid),s=q.companySnapshot||S.set;
 return`<div class="doc"><div class="hd"><div><b style="font-size:22px">${esc(s.name)}</b><br><small>${esc(s.tag)}</small></div><div style="text-align:right;font-size:12px">${esc(s.addr)}<br>${esc(s.phone)} · ${esc(s.email)}<br>${esc(s.web)} · GSTIN ${esc(s.gstin)}</div></div>
 <div class="grid" style="margin:14px 0"><div><b style="font-size:16px">QUOTATION</b><br>No: <b>${esc(q.no)}</b><br>Date: ${fd(q.date)}<br>Valid until: ${fd(q.valid)}<br>${q.project?'Project: '+esc(q.project)+'<br>':''}${q.subject?esc(q.subject):''}</div><div><b>Quoted to</b><br>${esc(c.name)}<br>${esc(c.co||'')}<br>${esc(c.addr||'')}<br>${esc(c.mob||'')} · ${esc(c.email||'')}<br>${c.gstin?'GSTIN '+esc(c.gstin):''}</div></div>
 <div class="tw"><table><tr><th>Sl.</th><th>Product / Service</th><th>Specifications</th><th class="n">Qty</th><th class="n">Unit price</th><th class="n">Amount</th></tr>${q.items.map((i,k)=>`<tr><td>${k+1}</td><td>${esc(i.name)}</td><td style="font-size:12px">${i.sp.map(esc).join('<br>')}${s.showNotes&&i.notes?'<br><i>Note: '+esc(i.notes)+'</i>':''}</td><td class="n">${i.qty}</td><td class="n">${inr(Math.round(i.sub/i.qty))}</td><td class="n">${inr(i.sub)}</td></tr>`).join('')}</table></div>
 ${sumHTML(q).replace(/class="mu">Items/,'style="display:none">Items')}
 <h3 style="font-size:13px">Terms and conditions</h3><ol style="font-size:12px;padding-left:18px">${q.terms.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="row" style="justify-content:space-between;margin-top:30px;font-size:12px"><span>Authorized Signatory</span><span>Customer Acceptance</span></div></div>`}
function pdfQ(id){return pdf(getQ(id))}async function pdfCur(){if(okQ(1)&&await saveQ(false))await pdf(Q)}
async function pdf(q){
 if(!q?.id){toast('Save this quotation before generating its PDF.','er');return}
 await downloadApi('/api/quotations/'+encodeURIComponent(q.id)+'/pdf',q.no.replace(/[^A-Za-z0-9_-]/g,'-')+'.pdf');
}
async function downloadApi(path,name){
 try{const response=await fetch(path,{credentials:'same-origin',cache:'no-store'});if(!response.ok){const data=await response.json();throw Object.assign(new Error(data.error||'Download failed.'),{status:response.status})}await out(await response.blob(),name);toast('Download ready')}
 catch(error){failure(error)}
}
/* --- all quotations --- */
const listRows=()=>{const k=F.q.toLowerCase(),r=S.quotes.filter(q=>{const c=cust(q.cid),t=tot(q).grand;return(!k||[q.no,c.name,c.co,c.mob,...q.items.map(i=>i.name)].join(' ').toLowerCase().includes(k))&&(!F.st||q.status===F.st)&&(!F.cu||q.cid===F.cu)&&(!F.sp||q.sales===F.sp)&&(!F.a||q.date>=F.a)&&(!F.b||q.date<=F.b)&&(!F.mn||t>=R(F.mn))&&(!F.mx||t<=R(F.mx))});
 return r.map(q=>`<tr><td>${esc(q.no)}</td><td>${fd(q.date)}</td><td>${esc(cust(q.cid).name)}</td><td>${esc(cust(q.cid).co)}</td><td class="n">${inr(tot(q).grand)}</td><td>${esc(q.by)}</td><td>${bg(q.status)}</td><td>${fd(q.valid)}</td><td>${acts(q)} <button class="s b2" onclick="statusQ('${q.id}')">Status</button> <button class="s bd" onclick="delQ('${q.id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan=9>No quotations match these filters.</td></tr>'};
V.list=()=>{const f=(k,ph,t)=>`<input style="width:auto;min-width:120px" type="${t||'text'}" placeholder="${ph}" value="${esc(F[k])}" oninput="F.${k}=this.value;$('#tb').innerHTML=listRows()">`;
 return`<h1>All Quotations</h1><div class="card"><div class="row">${f('q','Search number, customer, mobile, product')}<select style="width:auto" onchange="F.st=this.value;$('#tb').innerHTML=listRows()"><option value="">All statuses</option>${ST.map(s=>`<option ${F.st===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select style="width:auto" onchange="F.cu=this.value;$('#tb').innerHTML=listRows()"><option value="">All customers</option>${S.customers.map(c=>`<option value="${c.id}" ${F.cu===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select style="width:auto" onchange="F.sp=this.value;$('#tb').innerHTML=listRows()"><option value="">All salespeople</option>${[...new Set(S.quotes.map(q=>q.sales))].map(s=>`<option ${F.sp===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="row">${f('a','From','date')}${f('b','To','date')}${f('mn','Min ₹','number')}${f('mx','Max ₹','number')}</div><div class="tw"><table><tr><th>Number</th><th>Date</th><th>Customer</th><th>Company</th><th class="n">Total</th><th>By</th><th>Status</th><th>Valid until</th><th>Actions</th></tr><tbody id="tb">${listRows()}</tbody></table></div></div>`};
/* --- customers --- */
V.cust=()=>{const k=CQ.q.toLowerCase();return`<h1>Customers</h1><div class="row"><input style="max-width:280px" placeholder="Search customers" value="${esc(CQ.q)}" onchange="CQ.q=this.value;render()"><button class="bo" onclick="custForm('')">+ Add customer</button></div><div class="card tw"><table><tr><th>ID</th><th>Name</th><th>Company</th><th>Mobile</th><th>Email</th><th class="n">Quotes</th><th class="n">Quoted value</th><th>Actions</th></tr>${S.customers.filter(c=>!k||JSON.stringify(c).toLowerCase().includes(k)).map(c=>{const qs=S.quotes.filter(q=>q.cid===c.id);return`<tr><td>${c.id}</td><td>${esc(c.name)}</td><td>${esc(c.co)}</td><td>${esc(c.mob)}</td><td>${esc(c.email)}</td><td class="n">${qs.length}</td><td class="n">${inr(qs.reduce((a,q)=>a+tot(q).grand,0))}</td><td><button class="s b2" onclick="custView('${c.id}')">View</button> <button class="s b2" onclick="custForm('${c.id}')">Edit</button></td></tr>`}).join('')}</table></div>`};
function custView(id){const c=cust(id),qs=S.quotes.filter(q=>q.cid===id);modal(`<h2>${esc(c.name)}</h2><div class="mu">${esc(c.co)} · ${esc(c.mob)} · ${esc(c.email)} · ${esc(c.addr)} · ${esc(c.gstin)} · created ${fd(c.date)}<br>${esc(c.notes)}</div><h2 style="margin-top:12px">Previous quotations (total quoted ${inr(qs.reduce((a,q)=>a+tot(q).grand,0))})</h2>${qs.map(q=>`<div>${esc(q.no)} · ${fd(q.date)} · ${inr(tot(q).grand)} · ${bg(q.status)}</div>`).join('')||'None yet.'}`,640)}
function custForm(id,fromQ){const c=id?cust(id):{};const F_=(k,l,t)=>fld(l,`<input id="cf_${k}" type="${t||'text'}" value="${esc(c[k]||'')}">`);
 modal(`<h2>${id?'Edit':'Add'} customer</h2><div class="grid">${F_('name','Customer name *')}${F_('co','Company name')}${F_('person','Contact person')}${F_('mob','Mobile number *')}${F_('email','Email address')}${F_('gstin','GSTIN')}${F_('addr','Billing address')}${F_('notes','Notes')}</div><br><button onclick="custSave('${id}',${fromQ?1:0})">Save customer</button>`,720)}
async function custSave(id,fromQ,force,pending){
 if(busy)return;const v=pending||{};if(!pending)['name','co','person','mob','email','gstin','addr','notes'].forEach(k=>v[k]=$('#cf_'+k).value.trim());
 if(!v.name||!/^[0-9+ ()-]{10,20}$/.test(v.mob)){toast('Enter a customer name and a valid mobile number.','er');return}
 if(v.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email)){toast('Enter a valid email address.','er');return}
 const duplicate=S.customers.find(c=>c.id!==id&&((v.mob&&c.mob===v.mob)||(v.email&&c.email===v.email)||(v.gstin&&c.gstin===v.gstin)));
 if(duplicate&&!force){ask(`A customer with the same mobile, email or GSTIN already exists: ${esc(duplicate.name)}. Save a separate customer?`,()=>custSave(id,fromQ,true,v),'Save anyway');return}
 if(id)Object.assign(cust(id),v);else{id='C'+uid();S.customers.push({id,date:today(),...v})}
 if(!await persist()){if(!$('#cf_name'))custFormPending(id,fromQ,v);return}
 if(fromQ&&Q)Q.cid=id;closeM();render();toast('Customer saved');
}
function custFormPending(id,fromQ,v){custForm(S.customers.some(c=>c.id===id)?id:'',fromQ);Object.keys(v).forEach(k=>{const el=$('#cf_'+k);if(el)el.value=v[k]})}

/* --- products, categories, pricing --- */
const mlab=p=>p.m==='unit'?'Tiered per unit':p.m==='area'?`Per sq ft: ${inr(R(p.rate))}${p.min?' (min '+inr(R(p.min))+')':''}`:'Fixed package';
V.prod=()=>`<h1>Products &amp; Services</h1><div class="note">Sample prices are configurable demo values, not approved Design Paradise prices.</div><div class="row"><button class="bo" onclick="prodForm()">+ Add product</button></div><div class="card tw"><table><tr><th>Code</th><th>Product</th><th>Category</th><th>Pricing</th><th class="n">GST %</th><th>Status</th><th>Actions</th></tr>${S.products.map(p=>`<tr><td>${esc(p.code)}</td><td>${esc(p.name)}</td><td>${esc(cat(p.cat))}</td><td>${mlab(p)}${p.tiers?'<br><span class="mu">'+p.tiers.map(t=>t[0]+'+: '+t[1]).join(', ')+'</span>':''}</td><td class="n">${p.tax}</td><td>${p.on?'<span class="bg g">Active</span>':'<span class="bg r">Inactive</span>'}</td><td><button class="s b2" onclick="prodToggle('${p.id}')">${p.on?'Deactivate':'Activate'}</button> <button class="s b2" onclick="prodForm('${p.id}')">Edit</button> <button class="s bd" onclick="prodDel('${p.id}')">Remove</button></td></tr>`).join('')}</table></div>`;
async function prodToggle(id){if(busy||!admin())return;const p=prod(id);p.on=p.on?0:1;if(await persist()){render();toast('Product updated')}}
function prodDel(id){if(!admin())return;ask('Remove this product from the catalog? Existing quotations keep their saved snapshots.',async()=>{S.products=S.products.filter(p=>p.id!==id);if(await persist()){render();toast('Product removed')}},'Delete')}
function prodForm(id){if(!admin())return;const p=id?prod(id):{name:'',code:'',cat:S.cats[0]?.id||'',m:'unit',rate:0,tiers:[[1,0]],tax:S.set.tax,min:0};
 modal(`<h2>${id?'Edit':'Add'} product</h2><div class="grid">${fld('Name',`<input id="pn" value="${esc(p.name)}">`)}${fld('Code',`<input id="pc" value="${esc(p.code)}">`)}${fld('Category',`<select id="pk">${S.cats.map(c=>`<option value="${c.id}" ${c.id===p.cat?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`)}${fld('Pricing method',`<select id="pm"><option value="unit" ${p.m=='unit'?'selected':''}>Per unit (quantity tiers)</option><option value="area" ${p.m=='area'?'selected':''}>Per area (sq ft)</option><option value="fixed" ${p.m=='fixed'?'selected':''}>Fixed package</option></select>`)}${fld('Area rate / fixed fee (₹)',`<input id="pr" type="number" value="${p.rate}">`)}${fld('Quantity tiers (qty:rate, comma separated)',`<input id="pt" value="${(p.tiers||[]).map(t=>t.join(':')).join(',')}">`)}${fld('Minimum order charge (₹)',`<input id="pmn" type="number" value="${p.min}">`)}${fld('GST % (0 = exempt/zero-rated)',`<input id="px" type="number" value="${p.tax}">`)}</div><div class="mu">New products get a quantity, delivery and notes configuration; specific options can be edited under Pricing Configuration.</div><br><button onclick="prodSave('${id||''}')">Save product</button>`)}
async function prodSave(id){if(busy||!admin())return;const n=$('#pn').value.trim(),m=$('#pm').value,tiers=$('#pt').value.split(',').map(x=>x.split(':').map(Number)).filter(t=>t.length==2&&t[0]>0&&t[1]>=0).sort((a,b)=>a[0]-b[0]);
 if(!n){toast('Enter a product name.','er');return}if(m==='unit'&&!tiers.length){toast('Add at least one quantity tier, e.g. 100:5','er');return}
 const v={name:n,code:$('#pc').value||'NEW',cat:$('#pk').value,m,rate:+$('#pr').value||0,tiers:m==='unit'?tiers:null,min:+$('#pmn').value||0,tax:+$('#px').value||0};
 const fields=(id?prod(id).f:[DEL,NOTE]).filter(f=>f.t!=='dim');if(m==='area')fields.unshift({k:'dim',l:'Size',t:'dim'});v.f=fields;v.sizes=id&&prod(id).sizes&&m==='unit'?1:0;
 if(id)Object.assign(prod(id),v);else S.products.push({id:'p'+uid(),on:1,...v});if(!await persist())return;closeM();render();toast('Product saved')}
V.cat=()=>`<h1>Product Categories</h1><div class="row"><input id="nc" style="max-width:260px" placeholder="New category name"><button class="bo" onclick="catAdd()">Add category</button></div><div class="card tw"><table><tr><th>Category</th><th class="n">Products</th><th>Status</th><th>Actions</th></tr>${S.cats.map(c=>`<tr><td><input value="${esc(c.name)}" onchange="catName('${c.id}',this.value)"></td><td class="n">${S.products.filter(p=>p.cat===c.id).length}</td><td>${c.on?'Active':'Inactive'}</td><td><button class="s b2" onclick="catToggle('${c.id}')">${c.on?'Deactivate':'Activate'}</button> <button class="s bd" onclick="catDel('${c.id}')">Remove</button></td></tr>`).join('')}</table></div>`;
async function catAdd(){if(busy||!admin())return;const n=$('#nc').value.trim();if(!n){toast('Enter a category name.','er');return}S.cats.push({id:'c'+uid(),name:n,on:1});if(await persist()){render();toast('Category added')}}
async function catDel(id){if(busy||!admin())return;if(S.products.some(p=>p.cat===id)){toast("Move or remove this category's products first.",'er');return}S.cats=S.cats.filter(c=>c.id!==id);if(await persist()){render();toast('Category removed')}}
V.price=()=>`<h1>Pricing Configuration</h1><div class="note">Demo prices. Changes apply to new quotation items only; saved quotations keep their original snapshot prices. Option charge types: f = fixed per item, u = per unit, p = % of base, a = per sq ft.</div>${S.products.map(p=>`<details class="card"><summary><b>${esc(p.name)}</b> <span class="mu">${mlab(p)} · GST ${p.tax}%</span></summary><div class="grid" style="margin-top:10px">${fld('Area rate / fixed fee (₹)',`<input type="number" value="${p.rate}" onchange="priceField('${p.id}','rate',this.value)">`)}${fld('Min order charge (₹)',`<input type="number" value="${p.min}" onchange="priceField('${p.id}','min',this.value)">`)}${fld('GST %',`<input type="number" value="${p.tax}" onchange="priceField('${p.id}','tax',this.value)">`)}${p.tiers?fld('Tiers qty:rate',`<input value="${p.tiers.map(t=>t.join(':')).join(',')}" onchange="tiers_('${p.id}',this.value)">`):''}</div>${p.f.filter(f=>f.t==='sel').map(f=>`<div class="mu" style="margin-top:8px"><b>${esc(f.l)}</b></div><div class="row">${f.o.map((x,i)=>`<label class="mu">${esc(x[0])} <select style="width:auto" onchange="op_('${p.id}','${f.k}',${i},1,this.value)">${['f','u','p','a'].map(t=>`<option ${x[1]===t?'selected':''}>${t}</option>`).join('')}</select> <input type="number" step="any" style="width:80px" value="${x[2]}" onchange="op_('${p.id}','${f.k}',${i},2,this.value)"></label>`).join('')}</div>`).join('')}</details>`).join('')}`;
async function tiers_(id,v){if(busy||!admin())return;const t=v.split(',').map(x=>x.split(':').map(Number));if(!t.length||t.some(x=>x.length!==2||!Number.isFinite(x[0])||!Number.isFinite(x[1])||x[0]<=0||x[1]<0)){toast('Use quantity:price pairs, e.g. 100:5,500:4','er');render();return}prod(id).tiers=t.sort((a,b)=>a[0]-b[0]);if(await persist())toast('Tiers saved')}
async function op_(id,k,i,j,v){if(busy||!admin())return;prod(id).f.find(f=>f.k===k).o[i][j]=j===2?Number(v):v;if(await persist())toast('Option price saved')}
/* --- reports --- */
function repData(){return S.quotes.filter(q=>(!RF.a||q.date>=RF.a)&&(!RF.b||q.date<=RF.b))}
function grp(qs,fn){const m=Object.create(null);qs.forEach(q=>{const k=fn(q);(m[k]=m[k]||{n:0,v:0});m[k].n++;m[k].v+=tot(q).grand});return Object.entries(m)}
V.rep=()=>{const qs=repData(),tb=(h,rows)=>`<div class="card tw"><h2>${h[0]}</h2><table><tr>${h.slice(1).map((x,i)=>`<th class="${i?'n':''}">${x}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map((x,i)=>`<td class="${i?'n':''}">${esc(x)}</td>`).join('')}</tr>`).join('')||'<tr><td>No data</td></tr>'}</table></div>`;
 const pm=Object.create(null);qs.forEach(q=>q.items.forEach(i=>{pm[i.name]=pm[i.name]||[0,0];pm[i.name][0]++;pm[i.name][1]+=i.qty}));
 return`<h1>Reports</h1><div class="note">Totals are quoted values, not revenue or payments received.</div><div class="row"><input type="date" style="width:auto" value="${RF.a}" onchange="RF.a=this.value;render()"><input type="date" style="width:auto" value="${RF.b}" onchange="RF.b=this.value;render()"><button class="b2" onclick="repCsv()">Export visible reports to CSV</button></div><div class="mu">${qs.length} quotations · quoted value ${inr(qs.reduce((a,q)=>a+tot(q).grand,0))}</div><br>
 ${tb(['Quotations by status','Status','Count','Quoted value'],grp(qs,q=>q.status).map(([k,v])=>[k,v.n,inr(v.v)]))}${tb(['Quotations created by date','Date','Count','Quoted value'],grp(qs,q=>fd(q.date)).map(([k,v])=>[k,v.n,inr(v.v)]))}${tb(['Quotations by salesperson','Salesperson','Count','Quoted value'],grp(qs,q=>q.sales).map(([k,v])=>[k,v.n,inr(v.v)]))}${tb(['Most frequently quoted products','Product','Times quoted','Total quantity'],Object.entries(pm).sort((a,b)=>b[1][0]-a[1][0]).map(([k,v])=>[k,v[0],v[1]]))}${tb(['Customer-wise history','Customer','Count','Quoted value'],grp(qs,q=>cust(q.cid).name).map(([k,v])=>[k,v.n,inr(v.v)]))}${tb(['Approved vs rejected','Outcome','Count','Quoted value'],grp(qs.filter(q=>/^Customer (Approved|Rejected)$/.test(q.status)),q=>q.status).map(([k,v])=>[k,v.n,inr(v.v)]))}${tb(['Expired quotations','Quotation','Customer','Quoted value'],qs.filter(q=>q.status==='Expired').map(q=>[q.no,cust(q.cid).name,inr(tot(q).grand)]))}`};
function repCsv(){const query=new URLSearchParams();if(RF.a)query.set('from',RF.a);if(RF.b)query.set('to',RF.b);return downloadApi('/api/reports/quotations.csv?'+query,'quotation-report.csv')}

/* Same-origin authenticated backend connection. */
let AUTH=null,CSRF=null,REV=0,SAVED=null,SETD=null,TEAM=[],initialized=true,busy=false,conflict=false;
let connection={kind:'loading',text:'Connecting to the backend…'},expiredUser=null;
const privileged=new Set(['prod','cat','price','set']);
const termsFromText=value=>value.split(/\r?\n/).filter(Boolean);
const admin=()=>AUTH?.role==='Administrator';
const stateOnly=()=>Object.fromEntries(['cats','products','customers','quotes','log','set'].map(k=>[k,clone(S[k])]));
function adopt(data){S=clone(data.state);REV=data.revision;AUTH=data.user||AUTH;S.user=AUTH.name;S.role=AUTH.role;SAVED=stateOnly()}
function status(kind,text){connection={kind,text};const el=$('#connection');if(el)el.innerHTML=connectionHTML()}
function connectionHTML(){return `<div class="connection ${connection.kind}" role="status"><span class="dot"></span><span>${esc(connection.text)}</span>${conflict?'<button class="s b2" onclick="reloadState()">Reload latest data</button>':''}</div>`}
function lock(value){busy=value;document.body.classList.toggle('saving',value);document.querySelectorAll('button,input,select,textarea').forEach(el=>{if(value){if(el.dataset.wasDisabled===undefined)el.dataset.wasDisabled=el.disabled?'1':'0';el.disabled=true}else if(el.dataset.wasDisabled!==undefined){el.disabled=el.dataset.wasDisabled==='1';delete el.dataset.wasDisabled}})}
async function api(path,options={}){
 const method=options.method||'GET',headers={'Accept':'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(method!=='GET'&&CSRF?{'X-CSRF-Token':CSRF}:{})};
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);
 try{
  const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,headers,signal:controller.signal});
  const data=await response.json().catch(()=>({error:'The backend returned an unreadable response.'}));
  if(!response.ok){const error=new Error(typeof data.error==='string'?data.error:data.message||'Request failed.');error.status=response.status;throw error}
  return data;
 }catch(error){if(error.name==='AbortError')throw new Error('The backend took too long to respond. Check the connection before retrying.');if(error instanceof TypeError)throw new Error('Cannot reach the backend. Keep this tab open, start the server, then retry.');throw error}
 finally{clearTimeout(timer)}
}
function failure(error,stateConflict=false){
 if(error.status===401){expiredUser=AUTH?.id;AUTH=null;CSRF=null;closeM();status('error','Your session expired. Sign in again; your quotation draft is kept in this tab.');render()}
 else if(error.status===409&&stateConflict){conflict=true;status('error','Another session changed this workspace. Your save was not applied. Reload the latest data, review your draft, then save again.');render()}
 else status('error',error.message||'Your changes could not be saved.');
 toast(error.message||'Changes were not saved.','er');
}
function changedRecords(next,previous){
 const changes=[];
 for(const collection of ['cats','products','customers','quotes']){
  const old=new Map((previous?.[collection]||[]).map(x=>[x.id,x]));
  for(const record of next[collection]){if(JSON.stringify(record)!==JSON.stringify(old.get(record.id)))changes.push({collection,action:'upsert',id:record.id,record});old.delete(record.id)}
  for(const id of old.keys())changes.push({collection,action:'delete',id});
 }
 if(JSON.stringify(next.set)!==JSON.stringify(previous?.set))changes.push({collection:'set',action:'upsert',record:next.set});
 return changes;
}
async function persist(){
 if(busy)return false;
 if(conflict){if(SAVED){S=clone(SAVED);S.user=AUTH?.name;S.role=AUTH?.role}toast('Reload the latest workspace before saving again. Your quotation draft is preserved.','er');return false}
 const attempted=stateOnly(),changes=changedRecords(attempted,SAVED);if(!changes.length)return true;lock(true);status('loading','Saving to the backend…');
 try{const data=await api('/api/changes',{method:'POST',body:JSON.stringify({changes,revision:REV})});adopt(data);status('ok','Connected · All changes saved');return true}
 catch(error){if(SAVED){S=clone(SAVED);S.user=AUTH?.name;S.role=AUTH?.role}failure(error,true);if(AUTH&&!conflict)render();return false}
 finally{lock(false)}
}
async function reloadState(){
 if(busy)return;lock(true);
 try{adopt(await api('/api/state'));rebaseDraft();conflict=false;SETD=null;status('ok',Q?'Latest data loaded. Review your preserved quotation draft before saving.':'Connected · Latest data loaded');render()}
 catch(error){failure(error)}finally{lock(false)}
}
function authHTML(){
 const setup=!initialized;
 return `<main class="auth-layout"><section class="auth-intro"><div class="brand-mark">DP<span>DESIGN<br>PARADISE</span></div><div class="eyebrow">SALEM · LOVE YOUR BRAND</div><h1>A clearer path<br>from idea to quote.</h1><p>Your customers, product configurations and quotations in one connected workspace.</p><div class="auth-feature"><span>01</span> Configure products and pricing</div><div class="auth-feature"><span>02</span> Prepare professional quotations</div><div class="auth-feature"><span>03</span> Track every customer decision</div><small>Quotation Manager · Local workspace</small></section><section class="auth-panel"><div class="auth-card"><span class="eyebrow">${setup?'FIRST-TIME SETUP':'WELCOME BACK'}</span><h2>${setup?'Create your workspace':'Sign in to your workspace'}</h2><p class="mu">${setup?'Create the administrator account for this installation. Your data will be saved in the local database.':'Use your account to manage customers and quotations.'}</p><div id="connection">${connectionHTML()}</div><form onsubmit="event.preventDefault();signIn(${setup})">${setup?fld('Your name','<input name="name" id="auth_name" autocomplete="name" required maxlength="100">'):''}${fld('Username','<input name="username" id="auth_username" autocomplete="username" required minlength="3" maxlength="64" autocapitalize="none" spellcheck="false">')}${fld('Password',`<input name="password" id="auth_password" type="password" autocomplete="${setup?'new-password':'current-password'}" required ${setup?'minlength="12"':''} maxlength="128">`)}${setup?'<p class="mu">Use at least 12 characters for your password.</p><label class="checkbox"><input id="auth_demo" type="checkbox"> Include sample customers and quotations</label><p class="mu">A clearly labelled sample product catalog is included so you can configure your own prices.</p>':''}<button class="auth-submit" type="submit">${setup?'Create workspace':'Sign in'} <span aria-hidden="true">→</span></button></form><div class="auth-footer">${Q?'Your unsaved quotation draft is preserved in this tab.':'Connected to your local Design Paradise backend.'}</div></div></section></main>`;
}
function render(){
 if(!AUTH||!S){$('#app').innerHTML=authHTML();if(busy)lock(true);return}
 const h=(location.hash||'#dash').slice(1),v=V[h]&&(!privileged.has(h)||admin())?h:'dash';
 const nav=NAV.filter(n=>!privileged.has(n[0])||admin());
 $('#app').innerHTML=`<aside><div class="br"><div class="brand-symbol">DP</div><b>${esc(S.set.name)}</b><small>${esc(S.set.tag)}</small></div><div class="nav-label">WORKSPACE</div><nav>${nav.map(n=>`<a href="#${n[0]}" class="${n[0]===v?'on':''}" ${n[0]===v?'aria-current="page"':''}>${n[1]}</a>`).join('')}</nav><div class="account"><div class="avatar">${esc(AUTH.name.slice(0,1).toUpperCase())}</div><div><b>${esc(AUTH.name)}</b><small>${esc(AUTH.role)}</small></div><button class="account-link" onclick="passwordForm()">Change password</button><button class="account-link" onclick="sessionsForm()">Sessions</button><button class="account-link" onclick="signOut()">Sign out</button></div></aside><main><div class="workspace-top"><span>DESIGN PARADISE <span class="divider">/</span> ${esc(NAV.find(n=>n[0]===v)?.[1]||'Workspace')}</span><span>${esc(new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}))}</span></div><div id="connection">${connectionHTML()}</div>${V[v]()}</main>`;
 if(busy)lock(true);
 if(v==='rep'&&typeof loadServerReports==='function')loadServerReports();
 if(v==='set'){loadTeam();if(typeof loadBackendSettings==='function')loadBackendSettings();}
}
async function signIn(setup){
 if(busy)return;
 const body={username:$('#auth_username').value.trim(),password:$('#auth_password').value};
 if(setup){body.name=$('#auth_name').value.trim();body.demo=$('#auth_demo').checked;if(body.password.length<12){toast('Use a password with at least 12 characters.','er');return}}
 lock(true);status('loading',setup?'Creating your workspace…':'Signing in…');
 try{const data=await api(setup?'/api/auth/setup':'/api/auth/login',{method:'POST',body:JSON.stringify(body)});if(expiredUser&&expiredUser!==data.user.id)Q=null;AUTH=data.user;CSRF=data.csrfToken;initialized=true;adopt(await api('/api/state'));rebaseDraft();conflict=false;status('ok','Connected · All changes saved');closeM();render()}
 catch(error){status('error',error.message);toast(error.message,'er')}finally{lock(false)}
}
async function signOut(){
 if(busy)return;
 if(Q&&!confirm('Sign out? Any unsaved quotation draft in this tab will be discarded.'))return;
 lock(true);try{await api('/api/auth/logout',{method:'POST'});AUTH=null;CSRF=null;S=null;SAVED=null;Q=null;SETD=null;TEAM=[];conflict=false;closeM();status('ok','Signed out successfully.');render()}catch(error){failure(error)}finally{lock(false)}
}
async function start(){
 try{const data=await api('/api/auth/status');initialized=data.initialized;AUTH=data.user;CSRF=data.csrfToken;if(AUTH)adopt(await api('/api/state'));status('ok',initialized?'Connected to the local backend':'Backend connected · Ready to set up');render()}
 catch(error){connection={kind:'error',text:error.message};$('#app').innerHTML=`<main class="loading"><div class="card"><h1>Could not connect</h1><p>${esc(error.message)}</p><button onclick="start()">Retry connection</button></div></main>`}
}
async function catName(id,value){if(busy||!admin())return;const name=value.trim();if(!name){toast('Category name cannot be empty.','er');render();return}S.cats.find(c=>c.id===id).name=name;if(await persist())toast('Category saved')}
async function catToggle(id){if(busy||!admin())return;const c=S.cats.find(c=>c.id===id);c.on=c.on?0:1;if(await persist()){render();toast('Category updated')}}
async function priceField(id,key,value){if(busy||!admin())return;const n=Number(value);if(!Number.isFinite(n)||n<0){toast('Enter a non-negative number.','er');render();return}prod(id)[key]=n;if(await persist())toast('Pricing saved')}

V.set=()=>{
 if(!SETD)SETD=clone(S.set);const s=SETD;
 const input=(k,label,type)=>fld(label,`<input type="${type||'text'}" value="${esc(s[k])}" oninput="SETD.${k}=${type==='number'?'Number(this.value)':'this.value'}">`);
 return `<h1>Settings</h1><div class="card"><h2>Company details</h2><p class="mu">These details appear on customer quotations. Replace the placeholder details before issuing a quotation.</p><div class="grid">${input('name','Company name')}${input('tag','Tagline')}${input('addr','Office address')}${input('phone','Phone')}${input('email','Email')}${input('web','Website')}${input('gstin','GSTIN')}${input('prefix','Quotation number prefix')}${input('tax','GST % for quotation-level charges','number')}${input('valid','Default validity in days','number')}</div><label class="checkbox"><input type="checkbox" ${s.showNotes?'checked':''} onchange="SETD.showNotes=this.checked"> Show internal item notes on customer PDFs</label>${fld('Standard terms (one per line)',`<textarea rows="6" oninput="SETD.terms=termsFromText(this.value)">${esc(s.terms.join('\n'))}</textarea>`)}<br><button onclick="saveSettings()">Save settings</button></div><div class="card"><div class="row spread"><div><h2>Team access</h2><p class="mu">Administrators manage catalog, pricing, company settings and internal approvals. Employees manage customers and quotations.</p></div><button class="b2" onclick="userForm()">+ Add team member</button></div><div id="team-list" class="tw"><p class="mu">Loading team members…</p></div></div><div class="card"><h2>Persistent local storage</h2><p class="mu">Saved changes are stored by the backend and remain available after restarting the browser or server. Sample catalog prices must be reviewed before use.</p></div>`;
};
async function saveSettings(){if(busy||!admin())return;S.set=clone(SETD);if(await persist()){SETD=null;render();toast('Company settings saved')}}
async function loadTeam(){try{const data=await api('/api/users');TEAM=data.users;const el=$('#team-list');if(el)el.innerHTML=`<table><tr><th>Name</th><th>Username</th><th>Role</th></tr>${TEAM.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td><span class="bg">${esc(u.role)}</span></td></tr>`).join('')}</table>`}catch(error){const el=$('#team-list');if(el)el.textContent=error.message;if(error.status===401)failure(error)}}
function userForm(){if(!admin())return;modal(`<h2>Add team member</h2><form onsubmit="event.preventDefault();addUser()"><div class="grid">${fld('Name','<input id="team_name" required maxlength="100" autocomplete="name">')}${fld('Username','<input id="team_username" required minlength="3" maxlength="64" autocomplete="off" autocapitalize="none">')}${fld('Password (at least 12 characters)','<input id="team_password" type="password" required minlength="12" maxlength="128" autocomplete="new-password">')}${fld('Role','<select id="team_role"><option>Employee</option><option>Administrator</option></select>')}</div><br><button type="submit">Create account</button></form>`,620)}
async function addUser(){if(busy||!admin())return;const body={name:$('#team_name').value.trim(),username:$('#team_username').value.trim(),password:$('#team_password').value,role:$('#team_role').value};lock(true);try{await api('/api/users',{method:'POST',body:JSON.stringify(body)});closeM();await loadTeam();toast('Team member added');status('ok','Connected · Team account saved')}catch(error){failure(error)}finally{lock(false)}}
function passwordForm(){modal(`<h2>Change your password</h2><form onsubmit="event.preventDefault();changePassword()">${fld('Current password','<input id="current_password" type="password" required autocomplete="current-password">')}${fld('New password (at least 12 characters)','<input id="new_password" type="password" required minlength="12" maxlength="128" autocomplete="new-password">')}<br><button type="submit">Update password</button></form>`,440)}
async function changePassword(){if(busy)return;const body={currentPassword:$('#current_password').value,password:$('#new_password').value};lock(true);try{const data=await api('/api/auth/password',{method:'POST',body:JSON.stringify(body)});if(data.csrfToken)CSRF=data.csrfToken;if(data.user)AUTH=data.user;closeM();toast('Password changed');status('ok','Connected · Password updated')}catch(error){status('error',error.message);toast(error.message,'er')}finally{lock(false)}}
window.onhashchange=()=>{if((location.hash||'')!=='#set')SETD=null;render()};
window.addEventListener('beforeunload',event=>{if(busy){event.preventDefault();event.returnValue=''}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!busy)closeM()});
